+# backend — this repo's Cloudflare Worker segment
+
+Local pack (not portable — see [claudinite-lifecycle](../../../shared/packs/claudinite-lifecycle/RULES.md))
+for `backend/`: the Cloudflare Worker API and the `process-show` Workflow pipeline described in
+[`../../../../dev/design/architecture.md`](../../../../dev/design/architecture.md) and
+[`../../../../backend/README.md`](../../../../backend/README.md). Authored by the
+`growth-discover-packs` task once `backend/` became a self-contained sub-project with real,
+project-specific working knowledge no canon pack homes (there is no Cloudflare Workers/Wrangler
+canon pack) and the repo's general `wip` pack did not already capture.
+
+## Rules (`RULES.md`)
+
+Two prose rules: empirically-found Cloudflare-platform values belong in `wrangler.jsonc`'s `vars`
+with a dated comment, never a hardcoded constant; and how to verify a backend change locally
+(Node >=22, `npm test` in `backend/`, no account or network needed).
+
+## Checks
+
+| Check | Severity | Enforcement |
+|---|---|---|
+| `bindings-only-in-index` | blocking | declared check (`declared-checks.json`) + fixture (`bindings-only-in-index.test.mjs`) |
+
+`bindings-only-in-index` guards the ports-and-adapters boundary `backend/README.md` already
+documents: every rule under `backend/src/` is a plain module proved against the fakes in
+`backend/test/support/`, and only `backend/src/index.js` may touch a Cloudflare binding
+(`env.*`) or import `cloudflare:workers`."},{"filename":".claudinite/local/packs/backend/RULES.md","status":"added","additions":24,"changes":24,"patch":"@@ -0,0 +1,24 @@
+# backend — this repo's Cloudflare Worker segment
+
+Working rules for `backend/`, the Cloudflare side of the product (the Worker API and the
+`process-show` Workflow pipeline). Loaded into every session through the rules index, so what
+lands here should be a directive an agent can act on. A rule this segment's own structure can
+enforce lives in `declared-checks.json` instead — see `bindings-only-in-index` there for the
+ports-and-adapters boundary between `src/index.js` and the rest of `src/`.
+
+A lesson that would hold for Cloudflare Workers in general, not just this project, does not belong
+here — propose it to the Claudinite canon instead.
+
+- **Tuning a Cloudflare-platform behavior found empirically** (a chunk size, an undocumented
+  input ceiling, a rate limit) — put the value in `wrangler.jsonc`'s `vars`, with a comment
+  recording what was verified and when, never as a hardcoded constant in `src/`. Workers AI's
+  Whisper input ceiling is undocumented, so `TRANSCRIBE_CHUNK_SECONDS` and
+  `TRANSCRIBE_CHUNK_OVERLAP_SECONDS` are `vars` for exactly that reason — a value to turn once a
+  real show disagrees with it, not a constant to edit and redeploy.
+
+- **Verifying a backend change in an agent session** — install Node >=22 (`wrangler` needs it;
+  `backend/package.json`'s `engines` field pins it) and run `npm test` in `backend/`
+  (`node --test test/*.test.js`). It needs no Cloudflare account and no network: every rule
+  (routing, chunk planning, segmentation, laugh detection) runs as a plain module against the
+  fakes in `test/support/fakes.js`, so a change is verified locally rather than only by CI. What
+  those fakes cannot prove is named in `backend/README.md`'s "What these tests do not prove"."},{"filename":".claudinite/local/packs/backend/VERSIONS.md","status":"added","additions":12,"changes":12,"patch":"@@ -0,0 +1,12 @@
+# backend — change record
+
+Every change automatic work makes to this pack, newest first: a prose rule added or removed, a
+check created, a rule corrected against a probe or deleted as irrelevant. The row is written in
+the same PR as the change it describes, so this file diffs beside it.
+
+A run that changed nothing writes no row — this is the log of what happened to the pack, never a
+log of runs.
+
+| Date | Task | Change |
+|---|---|---|
+| 2026-08-24 | `growth-discover-packs` | Seeded the pack: added the wrangler-`vars`-for-empirical-values rule, the backend-verification rule, and the `bindings-only-in-index` check (with its see-it-fail fixture) for the `backend/` segment. |"},{"filename":".claudinite/local/packs/backend/bindings-only-in-index.test.mjs","status":"added","additions":87,"changes":87,"patch":"@@ -0,0 +1,87 @@
+// See-it-fail fixture for the backend pack's declared check
+// "backend/bindings-only-in-index" (declared-checks.json): fires when a file
+// under backend/src/ other than index.js touches a Cloudflare binding
+// (env.*) or imports cloudflare:workers, stays quiet on index.js itself and
+// on plain rule modules with no binding access. Runs the real check engine
+// against throwaway git fixtures — `node --test` needs no project-level test
+// runner.
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { execFileSync } from 'node:child_process';
+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { dirname, join } from 'node:path';
+
+import { buildContext } from '../../../shared/engine/checks/helpers/repo-context.mjs';
+import { loadDeclaredChecks } from '../../../shared/engine/checks/helpers/pattern-rules.mjs';
+import { runRule } from '../../../shared/engine/checks/helpers/work.mjs';
+
+const PACK_DIR = dirname(new URL(import.meta.url).pathname);
+const RULE_ID = 'backend/bindings-only-in-index';
+
+function findingsFor(files) {
+  const root = mkdtempSync(join(tmpdir(), 'backend-bindings-check-'));
+  try {
+    execFileSync('git', ['init', '--quiet'], { cwd: root });
+    for (const [path, content] of Object.entries(files)) {
+      const full = join(root, path);
+      mkdirSync(dirname(full), { recursive: true });
+      writeFileSync(full, content);
+    }
+    execFileSync('git', ['add', '-A'], { cwd: root });
+    const ctx = buildContext({ root, mode: 'all' });
+    const rule = loadDeclaredChecks(PACK_DIR).find((r) => r.id === RULE_ID);
+    assert.ok(rule, `${RULE_ID} must be declared in the backend pack`);
+    return runRule(rule, ctx);
+  } finally {
+    rmSync(root, { recursive: true, force: true });
+  }
+}
+
+test('fires when a src module outside index.js reads an env binding', () => {
+  const findings = findingsFor({
+    'backend/src/pipeline/segment.js': `
+export function segment(showId) {
+  return env.DB.prepare('select 1').run();
+}
+`,
+  });
+  assert.equal(findings.length, 1);
+  assert.equal(findings[0].line, 3);
+});
+
+test('fires when a src module outside index.js imports cloudflare:workers', () => {
+  const findings = findingsFor({
+    'backend/src/pipeline/process-show.js': `
+import { WorkflowEntrypoint } from 'cloudflare:workers';
+export class X extends WorkflowEntrypoint {}
+`,
+  });
+  assert.equal(findings.length, 1);
+  assert.equal(findings[0].line, 2);
+});
+
+test('stays quiet on index.js itself, which is where bindings turn into ports', () => {
+  const findings = findingsFor({
+    'backend/src/index.js': `
+import { WorkflowEntrypoint } from 'cloudflare:workers';
+export default {
+  async fetch(request, env) {
+    return env.DB.prepare('select 1').run();
+  },
+};
+`,
+  });
+  assert.equal(findings.length, 0);
+});
+
+test('stays quiet on a plain rule module with no binding access', () => {
+  const findings = findingsFor({
+    'backend/src/chunking/plan.js': `
+export function planChunks(durationSeconds, chunkSeconds) {
+  return Math.ceil(durationSeconds / chunkSeconds);
+}
+`,
+  });
+  assert.equal(findings.length, 0);
+});"},{"filename":".claudinite/local/packs/backend/declared-checks.json","status":"added","additions":21,"changes":21,"patch":"@@ -0,0 +1,21 @@
+[
+  {
+    "id": "backend/bindings-only-in-index",
+    "severity": "blocking",
+    "failureMessage": "A Cloudflare binding reached outside src/index.js — every rule must stay a plain module provable against the fakes; only index.js may turn a binding into a port.",
+    "scanFiles": "/^backend\\/src\\/.*\\.js$/",
+    "excludeFiles": "/^backend\\/src\\/index\\.js$/",
+    "matchLines": [
+      {
+        "match": "/\\benv\\.[A-Za-z_]/",
+        "what": "Cloudflare binding accessed outside index.js: {match}",
+        "fix": "move this binding access into src/index.js and pass the resulting port down, or add a fake for it in test/support/fakes.js"
+      },
+      {
+        "match": "/from ['\"]cloudflare:workers['\"]/",
+        "what": "cloudflare:workers imported outside index.js: {match}",
+        "fix": "only src/index.js may import cloudflare:workers"
+      }
+    ]
+  }
+]"},{"filename":".claudinite/local/packs/backend/pack.mjs","status":"added","additions":17,"changes":17,"patch":"@@ -0,0 +1,17 @@
+// backend — this repo's Cloudflare Worker segment: everything specific to
+// working in backend/, and portable nowhere else. Its rules, and the checks
+// that carry them, live here.
+//
+// The id is this directory's name and the prose is the RULES.md beside this
+// file — both by convention (engine/pack_loader/pack-conventions.mjs), so
+// neither is declared here.
+export default {
+  version: 1,
+  ruleRoutingGuidance: {
+    belongs: 'working rules for backend/ — the Cloudflare Worker: bindings, the Workflow, D1, R2, wrangler config',
+    excludes: "the Flutter app or any other segment — that's wip; portable Workers knowledge — propose it to the canon",
+  },
+  detect: null,
+  marker: null,
+  worldRules: [],
+};"}]

